        'experience': '',
        'job_url': job.get('url') or job.get('job_url') or '',
        'jd': job.get('description') or '',
        'source': job.get('source', 'jobspy'),
        'posted_date': str(job.get('date_posted', ''))
    })

return normalized

import json

analysis = {{$json}}
choices = analysis.get('choices', [])
if not choices:
    return {'error': 'No analysis result', 'overall_score': 0, 'recommended': False}

try:
    result = json.loads(choices[0].get('message', {}).get('content', '{}'))
except Exception:
    return {'error': 'Failed to parse LLM output', 'overall_score': 0, 'recommended': False}

if result.get('experience_status') == 'REJECT':
    result['overall_score'] = -1
    result['recommended'] = False

return result
